import zipfile

from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface

from ute_btssm.targetbd import TargetbdValidator
from ...exception import BTSSMExecutionError, ErrorFoundInCommandLineOutput


class SWUpdateInterface(BaseClToolInterface):
    OPERATION = 'swupdate'
    ROLLBACK_OPERATION = 'rollbacktopassivesw'
    STOP_UPDATE = 'stopupdate'

    def perform_swupdate_without_activation(self, targetbd, timeout='2h', **kwargs):
        """Perform a software update.

        :param string targetbd:  Path to the BTS software package.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        targetbd = TargetbdValidator.validate_targetbd(targetbd.strip()) if targetbd is not None else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'targetbd': targetbd, 'pw': pw, 'timeout': timeout, 'abortserver': 'on'}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_swupdate_operation(alias=alias, timeout=timeout, operation=SWUpdateInterface.OPERATION,
                                                   params=params, trs_ip=ne, flags=flags)

    def perform_swupdate_with_activation(self, targetbd, timeout='2h', waitforreset=False, **kwargs):
        """Perform a software update and activate the new software.

        :param string  targetbd:      Path to the BTS software package.
        :param boolean waitforreset:  Adds waitforreset flag when building reset command line operation.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        targetbd = TargetbdValidator.validate_targetbd(targetbd.strip()) if targetbd is not None else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['activate']
        if waitforreset:
            flags.append('waitforreset')
        if nolog:
            flags.append('nolog')
        params = {'ne': ne, 'targetbd': targetbd, 'pw': pw, 'timeout': timeout, 'abortserver': 'on'}
        return self._execute_cl_swupdate_operation(alias=alias, timeout=timeout, operation=SWUpdateInterface.OPERATION,
                                                   params=params, trs_ip=ne, flags=flags)

    def perform_rollback_to_passive_sw(self, timeout='2h', **kwargs):
        """Perform SW rollback to passive version.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation=SWUpdateInterface.ROLLBACK_OPERATION,
                                               params=params, trs_ip=ne, flags=flags)

    def stop_sw_update(self, timeout='2h', **kwargs):
        """Stops SW Update"""

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation=SWUpdateInterface.STOP_UPDATE,
                                               params={}, trs_ip=ne, flags=flags)
